"""Calcular Quality global (0..1) como ΣGoodCount / ΣTotalCount."""
ds = value["ds"]
if not ds or ds.getRowCount() == 0:
    return 0.0

def f(x):
    try:
        return float(x or 0)
    except:
        return 0.0

sum_good = 0.0
sum_tot  = 0.0
n = ds.getRowCount()

for r in range(n):
    sum_good += f(ds.getValueAt(r, "GoodCount"))
    sum_tot  += f(ds.getValueAt(r, "TotalCount"))

if sum_tot > 0:
    return sum_good / sum_tot

# Fallback: promedio simple de Quality por corrida si no hay totales
total_q = 0.0
for r in range(n):
    good = f(ds.getValueAt(r, "GoodCount"))
    tot  = f(ds.getValueAt(r, "TotalCount"))
    total_q += (good / tot) if tot > 0 else 0.0
return (total_q / n) if n > 0 else 0.0

